### `backend/src/app.ts`

```ts
import express, { Application } from 'express';
import cors from 'cors';
import helmet from 'helmet';
import morgan from 'morgan';
import healthRoutes from './routes/health.routes';
import { errorHandler } from './middleware/errorHandler';

export const createApp = (): Application => {
  const app = express();

  // Security & parsing middlewares
  app.use(helmet());
  app.use(cors({ origin: process.env.CORS_ORIGIN || '*' }));
  app.use(express.json());
  app.use(morgan('combined'));

  // API routes
  app.use('/api/health', healthRoutes);

  // Global error handler (must be after routes)
  app.use(errorHandler);

  return app;
};
```

### `backend/src/server.ts`

```ts
import { createApp } from './app';
import { PrismaClient } from '@prisma/client';

const PORT = process.env.PORT ? parseInt(process.env.PORT) : 4000;

// Initialise Prisma (ensures DB connection before server starts)
const prisma = new PrismaClient();
prisma
  .$connect()
  .then(() => {
    console.info('✅ Connected to PostgreSQL');
    const app = createApp();
    app.listen(PORT, () => {
      console.info(`🚀 Backend listening on http://localhost:${PORT}`);
    });
  })
  .catch((err) => {
    console.error('❌ Failed to connect to DB', err);
    process.exit(1);
  });
```

### `backend/src/routes/health.routes.ts`

```ts
import { Router } from 'express';
import { getHealth } from '../controllers/health.controller';

const router = Router();

/**
 * @route   GET /api/health
 * @desc    Simple health‑check endpoint
 */
router.get('/', getHealth);

export default router;
```

### `backend/src/controllers/health.controller.ts`

```ts
import { Request, Response, NextFunction } from 'express';

/**
 * Returns a JSON payload confirming the service is alive.
 */
export const getHealth = (req: Request, res: Response, next: NextFunction) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
    });
  } catch (err) {
    next(err);
  }
};
```

### `backend/src/middleware/errorHandler.ts`

```ts
import { Request, Response, NextFunction } from 'express';

/**
 * Centralised error handling.
 * In production we hide stack traces; in dev we expose them.
 */
export const errorHandler = (
  err: unknown,
  _req: Request,
  res: Response,
  _next: NextFunction,
) => {
  console.error(err);
  const status = (err as any).status || 500;
  const message =
    process.env.NODE_ENV === 'production'
      ? 'Internal Server Error'
      : (err as any).message || 'Unexpected error';

  res.status(status).json({ error: message });
};
```

