### ✅ Unit Tests – `greater_than_test.cpp`
```cpp
#include <gtest/gtest.h>
#include "greater_than.hpp"

using namespace aura;

TEST(MaxOfTwoTest, HandlesIntegers) {
    EXPECT_EQ(max_of_two(3, 7), 7);
    EXPECT_EQ(max_of_two(-5, -2), -2);
    EXPECT_EQ(max_of_two(10, 10), 10);
}

TEST(MaxOfTwoTest, HandlesFloatingPoint) {
    EXPECT_DOUBLE_EQ(max_of_two(3.14, 2.71), 3.14);
    EXPECT_DOUBLE_EQ(max_of_two(-0.1, -0.2), -0.1);
}

TEST(MaxOfManyTest, HandlesVector) {
    std::vector<int> v{1, 4, 2, 9, 5};
    EXPECT_EQ(max_of_many(v), 9);
}

TEST(MaxOfManyTest, HandlesEmptyContainer) {
    std::vector<int> empty;
    EXPECT_THROW(max_of_many(empty), std::invalid_argument);
}
```

*Why GoogleTest?*  
- Industry‑standard, easy CI integration.  
- Provides clear failure diagnostics.

---  

### 🛠️ Build – `CMakeLists.txt`
```cmake
cmake_minimum_required(VERSION 3.14)
project(greater_than LANGUAGES CXX)

set(CMAKE_CXX_STANDARD 17)
set(CMAKE_CXX_STANDARD_REQUIRED ON)

# ---- Library (header‑only) ---------------------------------
add_library(greater_than INTERFACE)
target_include_directories(greater_than INTERFACE
    $<BUILD_INTERFACE:${CMAKE_CURRENT_SOURCE_DIR}/include>
    $<INSTALL_INTERFACE:include>
)

# ---- Tests -------------------------------------------------
include(FetchContent)
FetchContent_Declare(
    googletest
    URL https://github.com/google/googletest/archive/refs/tags/v1.14.0.zip
)
FetchContent_MakeAvailable(googletest)

add_executable(greater_than_test tests/greater_than_test.cpp)
target_link_libraries(greater_than_test PRIVATE greater_than gtest_main)

enable_testing()
add_test(NAME greater_than_test COMMAND greater_than_test)
```

